import{loadV5DailyNote,loadV5RoomDetail,ledgerSummary,migrationInfo,selectV5DailyShit}from'./data.js?v=5.3.0-study-nook';

const list=value=>Array.isArray(value)?value:[];
const obj=value=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>`$${(Number(value)||0).toFixed(2)}`;
const text=value=>String(value??'').trim();
function safeText(value){if(value==null)return'';if(Array.isArray(value))return value.map(safeText).filter(Boolean).join(' · ');if(typeof value==='object')return safeText(value.label??value.title??value.name??value.value??value.status);const result=String(value).trim();return result==='[object Object]'?'':result}

function get(source,path){return path.split('.').reduce((value,key)=>value?.[key],source)}
function asRows(value){if(Array.isArray(value))return value.filter(Boolean);if(value&&typeof value==='object')return Object.values(value).filter(row=>row&&typeof row==='object');return[]}
function rows(source,...paths){for(const path of paths){const found=asRows(get(source,path));if(found.length)return found}return[]}
function isDone(row){return row?.done===true||row?.completed===true||['done','complete','completed','closed','archived'].includes(text(row?.status).toLowerCase())}
function rowTitle(row,fallback='Untitled'){return text(row?.text)||text(row?.title)||text(row?.name)||text(row?.label)||fallback}
function dateOf(row){return text(row?.date)||text(row?.startDate)||text(row?.dueDate)||text(row?.createdAt).slice(0,10)}
function dueDateOf(row){const due=text(row?.date)||text(row?.dueDate)||text(row?.due);return /^\d{4}-\d{2}-\d{2}$/.test(due)?due:''}
function timeOf(row){return text(row?.startTime)||text(row?.time)||text(row?.start)}
function dateTimeKey(row){return`${dateOf(row)}T${timeOf(row)||'99:99'}`}
function formatDate(value){if(!value)return'No date';const d=new Date(`${String(value).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'})}
function formatTime(value){if(!value)return'';const [h,m]=String(value).split(':').map(Number);if(!Number.isFinite(h))return String(value);const d=new Date();d.setHours(h,m||0,0,0);return d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
function currentMonth(today){return String(today||'').slice(0,7)}
function billIsCurrentMonth(bill,today){if(bill?.paid===true)return false;const month=currentMonth(today),due=text(bill?.dueDate)||text(bill?.due);if(/^\d{4}-\d{2}-\d{2}$/.test(due))return due.slice(0,7)===month;return Number(bill?.dueDay)>0}
function amountOf(row){return Number(row?.balance??row?.currentBalance??row?.amount??row?.value??0)||0}
function taskPriority(row,today){if(row?.protected)return 100;const date=dueDateOf(row);if(date&&date<today)return 80;if(date===today)return 70;const priority=text(row?.priority).toLowerCase();return{today:60,high:55,soon:40,normal:25,whenever:10,idea:0}[priority]??20}
function topTasks(state,today,limit=5){return rows(state,'life.tasks').filter(row=>!isDone(row)).sort((a,b)=>taskPriority(b,today)-taskPriority(a,today)).slice(0,limit)}
function editV4(label='Open in V4'){return`<a class="btn soft" href="../v4/?source=v5-preview">🍓 ${esc(label)}</a>`}
function empty(label){return`<div class="empty">${esc(label)}</div>`}
function hero(ey,title,lede,source=true){return`<section class="hero room-hero"><div class="ey">${ey}</div><h2>${esc(title)}</h2><p>${esc(lede)}</p>${source?'<div class="room-source">🍓 Your V4 information has been brought into V5</div>':''}</section>`}
function stats(items){return`<div class="room-stat-grid">${items.map(([label,value,sub])=>`<div class="room-stat"><small>${esc(label)}</small><b>${esc(value)}</b>${sub?`<span>${esc(sub)}</span>`:''}</div>`).join('')}</div>`}
function rowHtml(title,meta='',tail=''){return`<div class="room-row"><div class="room-row-main"><b>${esc(title)}</b>${meta?`<span>${esc(meta)}</span>`:''}</div>${tail?`<div class="room-row-tail">${tail}</div>`:''}</div>`}
function recordData(path,row){const packed=btoa(unescape(encodeURIComponent(JSON.stringify(row||{}))));return`data-v5-record-path="${esc(path)}" data-v5-record="${esc(packed)}"`}
function recordRow(path,row,meta='',tail='',fallback='Untitled'){return`<div class="room-row" role="button" tabindex="0" style="cursor:pointer" ${recordData(path,row)}><div class="room-row-main"><b>${esc(rowTitle(row,fallback))}</b>${meta?`<span>${esc(meta)}</span>`:''}</div>${tail?`<div class="room-row-tail">${tail}</div>`:''}</div>`}
function card(ey,title,content,{full=false,tiny=false,count=null,lede='',action='',className=''}={}){return`<section class="card ${full?'full':''} ${tiny?'tiny-hide':''} ${esc(className)}"><div class="card-head"><div><div class="ey">${ey}</div><h2>${esc(title)}</h2>${lede?`<p>${esc(lede)}</p>`:''}</div>${action|| (count===null?'':`<span class="count">${esc(count)}</span>`)}</div>${content}</section>`}
function page(content){return`<section class="page">${content}</section>`}
function roomGrid(...cards){return`<div class="grid">${cards.join('')}</div>`}
function routeButton(label,view,open='',lane=''){return`<button type="button" class="btn soft" data-route-view="${esc(view)}"${open?` data-route-open="${esc(open)}"`:''}${lane?` data-route-lane="${esc(lane)}"`:''}>${esc(label)}</button>`}
function routeRow(title,meta,view,open='',tail='',lane=''){return`<div class="room-row canonical-route" role="button" tabindex="0" data-route-view="${esc(view)}"${open?` data-route-open="${esc(open)}"`:''}${lane?` data-route-lane="${esc(lane)}"`:''}><div class="room-row-main"><b>${esc(title)}</b>${meta?`<span>${esc(meta)}</span>`:''}</div>${tail?`<div class="room-row-tail">${tail}</div>`:''}</div>`}

function dailySelect(name,label,options,value){return`<label class="daily-field"><span>${esc(label)}</span><select name="${esc(name)}"><option value="">Choose one</option>${options.map(option=>`<option value="${esc(option)}"${option===value?' selected':''}>${esc(option)}</option>`).join('')}</select></label>`}
function dailyText(name,label,value,placeholder){return`<label class="daily-field daily-field-wide"><span>${esc(label)}</span><textarea name="${esc(name)}" rows="3" placeholder="${esc(placeholder)}">${esc(value||'')}</textarea></label>`}
function detailedDailyForm(note){const value=key=>text(note?.[key]);return`<form class="daily-note-form" data-daily-note-form><div class="daily-selects">${dailySelect('mood','How do you feel?',['Great','Good','Okay','Low','Overwhelmed'],value('mood'))}${dailySelect('sleepHours','How much sleep?',['Under 4 hours','4–5 hours','6–7 hours','7–8 hours','8+ hours','Not sure'],value('sleepHours'))}${dailySelect('sleepQuality','Sleep quality',['Restless','Meh','Okay','Good','Really good'],value('sleepQuality'))}${dailySelect('energy','Energy level',['Very low','Low','Medium','Good','High'],value('energy'))}${dailySelect('stress','Stress level',['None','Low','Medium','High','Very high'],value('stress'))}${dailySelect('meds','Medication check',['Taken','Need to take later','Skipped','Not applicable'],value('meds'))}${dailySelect('food','Food check',['Ate regularly','Ate something','Need something easy','Not sure yet'],value('food'))}${dailySelect('movement','Movement',['Rest day','Gentle movement','Workout','Lots of movement'],value('movement'))}${dailySelect('social','Social battery',['Needed quiet','A little connection','Social day','Social battery low'],value('social'))}</div><div class="daily-writing">${dailyText('whatHappened','What happened today?',value('whatHappened'),'The facts, the chaos, or the little stuff.')}${dailyText('whatHelped','What helped?',value('whatHelped'),'A person, a snack, a break, a song…')}${dailyText('whatWasHard','What was hard?',value('whatWasHard'),'Name it without fixing it.')}${dailyText('win','One thing that counted',value('win'),'Tiny wins fully count.')}${dailyText('tomorrowFocus','Tomorrow’s gentle focus',value('tomorrowFocus'),'One doable next thing.')}${dailyText('notes','Anything else?',value('notes'),'Brain leftovers are welcome here.')}</div><div class="button-row daily-actions"><button type="submit" class="btn primary">🍓 Save today’s note</button><span>Saved only in this V5 preview.</span></div></form>`}

export function renderDailyNoteModal(date){const day=/^\d{4}-\d{2}-\d{2}$/.test(text(date))?text(date):new Date().toISOString().slice(0,10),note=loadV5DailyNote(day),form=detailedDailyForm(note).replace('data-daily-note-form',`data-daily-note-form data-note-date="${esc(day)}"`);return`<div class="detail-modal-backdrop daily-note-calendar-modal" data-daily-note-calendar><section class="detail-modal" role="dialog" aria-modal="true"><div class="detail-modal-head"><div><div class="ey">🪷 DAILY NOTE · ${esc(formatDate(day))}</div><h2>${note?'Your saved daily note':'A fresh daily note'}</h2><p>${note?'Update what matters and keep the rest as it was.':'This date has no note yet, so it starts empty.'}</p></div><button type="button" class="detail-modal-close" data-daily-note-close aria-label="Close daily note">×</button></div>${form}</section></div>`}

