 pings:{title:'Set a reminder with enough context',action:'New little ping',lede:'Choose when it matters and why, so the reminder can do its job.',fields:[['reminder','What should you remember?','textarea'],['urgency','Urgency','select',['Right now','Today','This week','Eventually','Just in case']],['when','When should it ping?','select',['Morning','Afternoon','Evening','A specific date','No preference']],['date','Specific date','date'],['repeat','Repeat','select',['Once','Daily','Weekly','Monthly','Never']],['place','Where or when does it matter?','text'],['pingNotes','Extra context','textarea']]},
 routines:{title:'Make routines fit real life',action:'New routine',lede:'Give the routine a rhythm, a starting point, and a low-energy version.',fields:[['routine','Routine name','text'],['type','Routine type','select',['Morning','Night','Work','Study','Reset']],['rhythm','How often?','select',['Every day','Weekdays','A few times a week','Weekly','As needed']],['time','When does it usually happen?','select',['Morning','Midday','Afternoon','Evening','Whenever']],['cue','What starts the routine?','text'],['energyVersion','Low-energy version','textarea'],['skipRule','When is skipping okay?','select',['Never','When sick or hurting','On rest days','When capacity is low','Whenever needed']],['routineNotes','Steps, cues, or notes','textarea']]},
