 hobbies:{title:'Give fun a real place to land',action:'Add hobby',lede:'Track what sounds good, how much energy it takes, and the next playful step.',fields:[['hobby','Hobby','text'],['category','What kind of fun is it?','select',['Creative','Collecting','Games','Learning','Watching','Out and about']],['status','Where is it right now?','select',['Curious','Trying it','Currently playing','Paused','Someday']],['energy','Energy needed','select',['Tiny','Low','Medium','High','Hyperfixation']],['mood','How does it make you feel?','select',['Cozy','Curious','Creative','Excited','Calm']],['time','How much time do you have?','select',['5 minutes','15 minutes','30 minutes','An hour','A whole afternoon','No idea']],['next','Next playful step','text'],['hobbyNotes','Ideas or notes','textarea']]},
 money:{title:'Log the money detail',action:'New ledger entry',lede:'Keep the numbers clear: what moved, where it went, and what it means.',fields:[['entry','What happened?','textarea'],['kind','Entry type','select',['Spending','Income','Transfer','Bill','Savings']],['account','Account','text'],['amount','Amount','number'],['date','Date','date'],['category','Category','select',['Rent','Bills','Food','Transportation','Work','Fun','Savings','Other']],['toAccount','Transfer to','text'],['moneyNotes','Money notes','textarea']]},
 study:{title:'Set up a study session',action:'New study plan',lede:'Name the course, the kind of work, and the smallest finish line.',fields:[['course','Course or subject','text'],['goal','What are you trying to finish?','textarea'],['activity','Study activity','select',['Read','Watch','Practice','Write','Review']],['energy','Study energy','select',['Low','Medium','High','Focused','Scattered']],['sessionLength','How long is this block?','select',['15 minutes','30 minutes','45 minutes','1 hour','Longer']],['due','Due date','date'],['next','First study step','text'],['studyNotes','Notes or questions','textarea']]},
